import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }>, dueDate?: string, paid?: Array<{ amount: number }>, voucher?: { amount: number } }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // First line: invoice number or DRAFT
  const header = invoice.number ? invoice.number : 'DRAFT';

  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;

  // Build lines array
  const lines = [header, customerName];

  // Add line items with per-line discounts
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const lineText = `${line.qty} ${line.name} ${formatEuros(line.unitPrice)} ${formatEuros(total)}`;
    lines.push(lineText);

    if (line.discountPercent) {
      const discount = Math.round(total * (line.discountPercent / 100));
      lines.push(`  Discount (${line.discountPercent}%): -${formatEuros(discount)}`);
    }
  }

  // Add totals
  const totals = invoiceTotals(invoice);
  lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);

  if (totals.discount > 0) {
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }

  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  if (invoice.voucher) {
    lines.push(`Voucher: -${formatEuros(invoice.voucher.amount)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Add due date if available
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Add paid amount if there are payments
  const paid = invoice.paid ? invoice.paid.reduce((sum, p) => sum + p.amount, 0) : 0;
  if (paid > 0) {
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}

